function countOfArrays(n, m, k) {
  const MOD = 1000000007;
  const evens = Math.floor(m / 2);
  const odds = m - evens;
  let endEven = new Array(k + 1).fill(0);
  let endOdd = new Array(k + 1).fill(0);
  endEven[0] = evens;
  endOdd[0] = odds;

  for (let length = 2; length <= n; length++) {
    const nextEven = new Array(k + 1).fill(0);
    const nextOdd = new Array(k + 1).fill(0);
    for (let marked = 0; marked <= k; marked++) {
      nextOdd[marked] = (endEven[marked] + endOdd[marked]) * odds % MOD;
      const fromOdd = endOdd[marked];
      const fromEven = marked > 0 ? endEven[marked - 1] : 0;
      nextEven[marked] = (fromOdd + fromEven) * evens % MOD;
    }
    endEven = nextEven;
    endOdd = nextOdd;
  }
  return (endEven[k] + endOdd[k]) % MOD;
}

