function countOfArrays(n, m, k) {
  // Counted with combinatorics instead of a DP. Only the even/odd pattern matters, and if the e even values of a
  // pattern form r separate runs, exactly e - r indices are marked. So r = e - k: choose r of the n - e + 1 gaps
  // around the odd values for the runs, and split the e evens into r non-empty runs.
  const MOD = 1000000007;
  const mul = (a, b) => Number(BigInt(a) * BigInt(b) % BigInt(MOD));
  const C = [[1]];
  for (let a = 1; a <= n + 1; a++) {
    C[a] = [1];
    for (let b = 1; b <= a; b++) C[a][b] = ((C[a - 1][b - 1] ?? 0) + (C[a - 1][b] ?? 0)) % MOD;
  }
  const choose = (a, b) => (b < 0 || a < 0 || b > a ? 0 : C[a][b]);
  const power = (base, exp) => { let r = 1; for (let i = 0; i < exp; i++) r = r * base % MOD; return r; };
  const evens = Math.floor(m / 2), odds = m - evens;
  let total = k === 0 ? power(odds, n) : 0; // the pattern with no even value at all
  for (let e = k + 1; e <= n; e++) {
    const runs = e - k;
    const patterns = mul(choose(n - e + 1, runs), choose(e - 1, runs - 1));
    total = (total + mul(mul(patterns, power(evens, e)), power(odds, n - e))) % MOD;
  }
  return total;
}

