function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(600, 750);
    const m = rand() < 0.2 ? int(1, 5) : int(2, 1000);
    return [n, m, int(0, n - 1)];
  }
  const n = int(1, 8);
  const m = rand() < 0.7 ? int(1, 6) : int(1, 1000);
  return [n, m, int(0, n - 1)];
}
